<?php
if (!$PCC->tableExists('rp_player_documents') || !$PCC->tableExists('rp_document_types')): ?>
<section class="pcc-panel"><div class="pcc-empty"><i class="fas fa-id-card"></i><strong>Backend Documents V2 absent</strong><span>Les tables rp_player_documents / rp_document_types ne sont pas présentes dans cette base.</span></div></section>
<?php return; endif;
$q=trim((string)($_GET['q']??''));$status=strtoupper(trim((string)($_GET['status']??'')));$type=trim((string)($_GET['type']??''));$page=max(1,(int)($_GET['p']??1));$per=50;$offset=($page-1)*$per;
$where=array('1=1');$types='';$params=array();
$joins=' INNER JOIN rp_document_types t ON t.id=d.document_type_id INNER JOIN users u ON u.id=d.user_id';
$char=$PCC->tableExists('rp_characters');if($char)$joins.=' LEFT JOIN rp_characters c ON c.user_id=u.id';
if($q!==''){$like='%'.mb_substr($q,0,64).'%';$bits=array('u.username LIKE ?','d.document_number LIKE ?');$types.='ss';$params[]=$like;$params[]=$like;if($char){$bits[]='c.citizen_id LIKE ?';$bits[]="CONCAT(COALESCE(c.first_name,''),' ',COALESCE(c.last_name,'')) LIKE ?";$types.='ss';$params[]=$like;$params[]=$like;}$where[]='('.implode(' OR ',$bits).')';}
if($status!==''&&preg_match('/^[A-Z_]{2,20}$/',$status)){$where[]='UPPER(d.status)=?';$types.='s';$params[]=$status;}
if($type!==''&&preg_match('/^[A-Za-z0-9_\-]{1,40}$/',$type)){$where[]='t.code=?';$types.='s';$params[]=$type;}
$count=$DB->PreparedRow('SELECT COUNT(*) total FROM rp_player_documents d'.$joins.' WHERE '.implode(' AND ',$where),$types,$params);$total=$count?(int)$count['total']:0;$pages=max(1,(int)ceil($total/$per));if($page>$pages){$page=$pages;$offset=($page-1)*$per;}
$cols='d.id,d.user_id,d.document_number,d.issued_at,d.expires_at,d.status,t.code,t.name,t.category,u.username,u.look'.($char?',c.first_name,c.last_name,c.citizen_id':',NULL first_name,NULL last_name,NULL citizen_id');
$rows=$DB->PreparedAll('SELECT '.$cols.' FROM rp_player_documents d'.$joins.' WHERE '.implode(' AND ',$where).' ORDER BY d.id DESC LIMIT '.$per.' OFFSET '.(int)$offset,$types,$params);
$typeRows=$DB->PreparedAll('SELECT code,name FROM rp_document_types ORDER BY category,name');
$link=function($p)use($q,$status,$type){return URL.'/admin.php?'.http_build_query(array('page'=>'documents','q'=>$q,'status'=>$status,'type'=>$type,'p'=>$p));};
?>
<section class="pcc-panel"><form class="pcc-filterbar" method="get"><input type="hidden" name="page" value="documents"><div class="pcc-search-field"><i class="fas fa-search"></i><input name="q" value="<?php echo $h($q); ?>" placeholder="Joueur, nom RP, Citizen ID, numéro document…"></div><select class="pcc-select-compact" name="type"><option value="">Tous les types</option><?php foreach($typeRows as $t):?><option value="<?php echo $h($t['code']); ?>" <?php echo $type===$t['code']?'selected':''; ?>><?php echo $h($t['name']); ?></option><?php endforeach;?></select><select class="pcc-select-compact" name="status"><option value="">Tous les statuts</option><?php foreach(array('VALID','SUSPENDED','REVOKED','EXPIRED') as $s):?><option <?php echo $status===$s?'selected':''; ?>><?php echo $s;?></option><?php endforeach;?></select><button class="pcc-button secondary">Filtrer</button><span class="pcc-filter-count"><?php echo $number($total); ?> document(s)</span></form><div class="pcc-table-wrap"><table class="pcc-table pcc-table-dense"><thead><tr><th>Propriétaire</th><th>Nom RP</th><th>Citizen ID</th><th>Type</th><th>Numéro</th><th>Statut</th><th>Délivré</th><th>Expiration</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="9"><div class="pcc-empty compact"><strong>Aucun document trouvé</strong></div></td></tr><?php endif;?><?php foreach($rows as $row):$name=trim((string)$row['first_name'].' '.(string)$row['last_name']);?><tr><td><div class="pcc-user-cell"><img class="pcc-table-avatar" src="<?php echo $h($PCC->avatarUrl($row['look'],'s'));?>" alt=""><span><strong><?php echo $h($row['username']);?></strong><small class="pcc-subline">#<?php echo (int)$row['user_id'];?></small></span></div></td><td><?php echo $name!==''?$h($name):'—';?></td><td><code><?php echo $row['citizen_id']?$h($row['citizen_id']):'—';?></code></td><td><strong><?php echo $h($row['name']);?></strong><small class="pcc-subline"><?php echo $h($row['code']);?></small></td><td><code><?php echo $h($row['document_number']);?></code></td><td><span class="pcc-badge <?php echo strtoupper($row['status'])==='VALID'?'success':(strtoupper($row['status'])==='REVOKED'?'danger':'warning');?>"><?php echo $h($row['status']);?></span></td><td><?php echo $h($PCC->formatDate($row['issued_at']));?></td><td><?php echo $row['expires_at']?$h($PCC->formatDate($row['expires_at'])):'—';?></td><td><a class="pcc-button small secondary" href="<?php echo URL;?>/admin.php?page=player&id=<?php echo (int)$row['user_id'];?>&tab=documents">Ouvrir</a></td></tr><?php endforeach;?></tbody></table></div><?php if($pages>1):?><div class="pcc-pagination"><?php if($page>1):?><a href="<?php echo $h($link($page-1));?>">‹</a><?php endif;?><?php for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++):?><a class="<?php echo $i===$page?'is-active':'';?>" href="<?php echo $h($link($i));?>"><?php echo $i;?></a><?php endfor;?><?php if($page<$pages):?><a href="<?php echo $h($link($page+1));?>">›</a><?php endif;?></div><?php endif;?></section>
